CREATE TABLE IF NOT EXISTS `mob` (
  `ClassType` text DEFAULT NULL,
  `TranslationId` text DEFAULT NULL,
  `Name` varchar(255) NOT NULL,
  `Suffix` text DEFAULT NULL,
  `Guild` text DEFAULT NULL,
  `ExamineArticle` text DEFAULT NULL,
  `MessageArticle` text DEFAULT NULL,
  `X` int(11) NOT NULL DEFAULT 0,
  `Y` int(11) NOT NULL DEFAULT 0,
  `Z` int(11) NOT NULL DEFAULT 0,
  `Speed` int(11) NOT NULL DEFAULT 0,
  `Heading` smallint(5) unsigned NOT NULL DEFAULT 0,
  `Region` smallint(5) unsigned NOT NULL DEFAULT 0,
  `Model` smallint(5) unsigned NOT NULL DEFAULT 0,
  `Size` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `Strength` smallint(6) NOT NULL DEFAULT 0,
  `Constitution` smallint(6) NOT NULL DEFAULT 0,
  `Dexterity` smallint(6) NOT NULL DEFAULT 0,
  `Quickness` smallint(6) NOT NULL DEFAULT 0,
  `Intelligence` smallint(6) NOT NULL DEFAULT 0,
  `Piety` smallint(6) NOT NULL DEFAULT 0,
  `Empathy` smallint(6) NOT NULL DEFAULT 0,
  `Charisma` smallint(6) NOT NULL DEFAULT 0,
  `Level` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `Realm` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `EquipmentTemplateID` text DEFAULT NULL,
  `ItemsListTemplateID` text DEFAULT NULL,
  `NPCTemplateID` int(11) NOT NULL DEFAULT 0,
  `Race` int(11) NOT NULL DEFAULT 0,
  `Flags` int(10) unsigned NOT NULL DEFAULT 0,
  `AggroLevel` int(11) NOT NULL DEFAULT 0,
  `AggroRange` int(11) NOT NULL DEFAULT 0,
  `MeleeDamageType` int(11) NOT NULL DEFAULT 0,
  `RespawnInterval` int(11) NOT NULL DEFAULT 0,
  `FactionID` int(11) NOT NULL DEFAULT 0,
  `BodyType` int(11) NOT NULL DEFAULT 0,
  `HouseNumber` int(11) NOT NULL DEFAULT 0,
  `Brain` text DEFAULT NULL,
  `PathID` text DEFAULT NULL,
  `OwnerID` varchar(255) NOT NULL DEFAULT '',
  `RoamingRange` int(11) NOT NULL DEFAULT 0,
  `IsCloakHoodUp` tinyint(1) NOT NULL DEFAULT 0,
  `Gender` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `PackageID` text DEFAULT NULL,
  `VisibleWeaponSlots` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `LastTimeRowUpdated` datetime NOT NULL DEFAULT '2000-01-01 00:00:00',
  `Mob_ID` varchar(255) NOT NULL,
  PRIMARY KEY (`Mob_ID`),
  KEY `I_Mob_Name` (`Name`),
  KEY `I_Mob_HouseNumber` (`HouseNumber`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;


